    "generated_rules": "जेनरेट किए गए नियम",
    "ios_named_acl": "! नामित ACL समकक्ष:",
    "rule_name": "नियम_नाम",
    "explanation": "मैकेनिक्स और लॉजिक स्पष्टीकरण",
    "permit": "अनुमति दें",
    "deny": "Deny",
    "explanation_iptables_filter": "iptables डिफ़ॉल्ट रूप से 'filter' टेबल का उपयोग करता है। 'INPUT' स्थानीय सिस्टम के लिए नियत पैकेट को संभालता है, जबकि 'FORWARD' माध्यम से गुजरने वाले ट्रैफ़िक (routing) को संभालता है। सुरक्षा के लिए स्टेटफुल रूल्स (conntrack का उपयोग करके) की सिफारिश की जाती है।",
    "explanation_masquerade": "Masquerading Dynamic SNAT का एक रूप है। यह सोर्स IP को आउटगोइंग इंटरफ़ेस ({iface}) के IP से बदल देता है। इसका उपयोग निजी LAN को डायनेमिक सार्वजनिक IP के माध्यम से इंटरनेट एक्सेस देने के लिए किया जाता है।",
    "explanation_snat": "Static SNAT (Source NAT) सोर्स IP को एक निश्चित पते ({target}) से बदल देता है। इसका उपयोग तब किया जाता है जब गेटवे के पास कई स्थिर IP होते हैं।",
    "explanation_dnat": "DNAT (Destination NAT) या Port Forwarding आने वाले पैकेट के गंतव्य IP/पोर को संशोधित करता है। यह बाहरी उपयोगकर्ताओं को आपके निजी नेटवर्क के अंदर सर्वर तक पहुँचने की अनुमति देता।",
    "explanation_nftables": "nftables, iptables का आधुनिक प्रतिस्थापन है। यह एक ही 'nft' टूल का उपयोग करता है और 'inet' टेबल का समर्थन करता है जो IPv4 और IPv6 दोनों को संभालता है। NAT रूल्स को 'nat' टेबल में हुक के रूप में जोड़ा जाता है, आमतौर पर प्रिरूटिंग के लिए प्राथमिकता -100 और पोस्ट्रूटिंग के लिए 100 के साथ।",
    "explanation_default": "यह कॉन्फ़िगरेशन चयनित प्लेटफ़ॉर्म के लिए आवश्यक सिंटैक्स उत्पन्न करता है। अधिकांश फ़ायरवॉल नीतियां ऊपर-से-नीचे निष्पादन क्रम का पालन करती हैं।",
    "generate": "Generate Rules",
    "platform_cisco_ios": "Cisco IOS / IOS-XE",
