    "desc_root_port": "Root Bridge की ओर सबसे अच्छा रास्ता। प्रत्येक non-root switch पर एक। RSTP में Proposal/Agreement के तुरंत बाद Forwarding में प्रवेश करता है।",
    "desc_designated_port": "Root की ओर प्रत्येक LAN सेगमेंट पर सबसे अच्छा पोर्ट। एकमात्र पोर्ट जो उस सेगमेंट पर BPDUs फॉरवर्ड करता है।",
    "desc_alternate_port": "केवल RSTP। दूसरे bridge से बेहतर BPDU प्राप्त करता है। अपस्ट्रीम विफलता पर तुरंत Root Port में बदल जाता है — बिना किसी टाइमर प्रतीक्षा के।",
    "desc_backup_port": "केवल RSTP। उसी सेगमेंट (hub/loop) पर अपने स्वयं के bridge से बेहतर BPDU प्राप्त करता है। आधुनिक नेटवर्क में दुर्लभ।",
    "desc_non_designated": "केवल STP (802.1D)। BPDUs प्राप्त करता है लेकिन डेटा फॉरवर्ड नहीं करता है। topology परिवर्तन पर Listening→Learning के माध्यम से बदलता है।",
    "desc_edge_port": "लिंक-अप पर सीधे Forwarding पर जाता है (Listening/Learning को छोड़ देता है)। यदि इसे कभी BPDU प्राप्त होता है तो TCN भेजता है। केवल एंड-डिवाइस के लिए।",
