    "how_maps_desc_4": "3. 8 हार्डवेयर बकेट (0-7) इन सूचकांकों में वितरित किए जाते हैं। आपके वर्तमान {links}-लिंक कॉन्फ़िगरेशन में, लोड मास्क दिखाता है कि कौन से बकेट प्रत्येक इंटरफ़ेस से संबंधित हैं।",
    "how_maps_desc_5": "4. चूंकि आपका हैश परिणाम {rbh} है, इसलिए ट्रैफ़िक इंडेक्स {idx} ({label}) पर इंटरफ़ेस से बाहर भेजा जाता है।",
