    "mpls_title": "MPLS — Multi-Protocol Label Switching",
    "mpls_desc": "MPLS Layer 2 और Layer 3 हेडर के बीच एक 32-बिट लेबल डालता है, जिससे \"Layer 2.5\" शिम बनता है। पैकेटों को पूर्ण IP लुकअप करने के बजाय प्रत्येक LSR (Label Switching Router) पर लेबल स्वैप करके फॉरवर्ड किया जाता है — जिससे तेज़ फॉरवर्डिंग, ट्रैफ़िक इंजीनियरिंग और VPN सक्षम होते हैं।",
    "label_size": "लेबल का आकार",
    "label_field": "लेबल फ़ील्ड",
    "stack_depth": "स्टैक की गहराई",
    "reserved_labels": "Reserved लेबल्स",
    "mpls_header_title": "MPLS लेबल हेडर — 32 bits (4 bytes)",
    "click_field": "— विवरण के लिए फ़ील्ड पर क्लिक करें",
    "label": "लेबल",
    "tc": "TC",
    "s_bit": "S",
    "ttl": "TTL",
    "label_desc": "20-बिट फॉरवर्डिंग लेबल। मान 0-15 आरक्षित (reserved) हैं। राउटर प्रत्येक LSR हॉप पर इस मान को स्वैप या पॉप करते हैं।",
    "tc_desc": "Traffic Class (पूर्व में EXP)। QoS/CoS मार्किंग के लिए 3 बिट्स — MPLS डोमेन के अंदर DSCP या कतार प्राथमिकता के लिए मैप करता है।",
    "s_desc": "Bottom-of-Stack बिट। अंतरतम (innermost) लेबल पर 1 पर सेट होता है। जब S=1 होता है, तो अगला हेडर मूल IP पैकेट होता है।",
    "ttl_desc": "Time To Live। प्रत्येक LSR पर घटाया जाता है, वही भूमिका जो IP TTL की है। लेबल लूप को रोकता है। प्रवेश (ingress) पर IP TTL से कॉपी किया गया।",
    "encap_stack": "MPLS एनकैप्सुलेशन स्टैक",
    "label_outer": "MPLS लेबल #1 (बाहरी)",
    "label_inner": "MPLS लेबल #2 (आंतरिक)",
    "transport_label": "Ingress LER द्वारा धकेला गया — transport लेबल",
    "vpn_label": "VPN लेबल (L3VPN / 6PE)। इस लेबल पर S=1",
    "ip_hdr_desc": "मूल ग्राहक पैकेट — कोर में अपरिवर्तित",
    "tcp_udp_desc": "Transport लेयर, MPLS द्वारा अछूती",
    "label_ops": "लेबल संचालन (Label Operations)",
    "push_desc": "MPLS डोमेन में प्रवेश करने वाले बिना लेबल वाले IP पैकेट में एक या अधिक लेबल जोड़ता है।",
    "swap_desc": "शीर्ष लेबल को नए आउटगोइंग लेबल के साथ बदलता है और पैकेट को फॉरवर्ड करता है।",
    "pop_desc": "शीर्ष लेबल हटाता है। PHP (Penultimate Hop Popping) निकास (egress) से एक हॉप पहले पॉप करता है।",
    "php_desc": "निकास से पहले का अंतिम LSR transport लेबल को पॉप करता है, जिससे निकास LER का काम कम हो जाता है। Implicit-null लेबल (3) PHP का संकेत देता है।",
    "reserved_values": "आरक्षित लेबल मान (0–15)",
    "ldp_protocols": "लेबल वितरण प्रोटोकॉल (Label Distribution Protocols)",
    "ldp_desc": "Label Distribution Protocol। IGP-आधारित पथों के लिए हॉप-दर-हॉप लेबल वितरण। बुनियादी MPLS के लिए सबसे आम।",
    "rsvp_desc": "Resource Reservation Protocol जिसमें ट्रैफ़िक इंजीनियरिंग विस्तार हैं। बैंडविड्थ गारंटी के साथ स्पष्ट लेबल-स्विच्ड पथ (LSPs) स्थापित करता है।",
    "bgp_lu_desc": "BGP Labeled Unicast। BGP प्रिफ़िक्स के साथ लेबल वितरित करता है — इंटर-AS MPLS VPNs और सेगमेंट रूटिंग में उपयोग किया जाता है।",
    "sr_mpls_desc": "Segment Routing over MPLS। लेबल रूटिंग निर्देशों (node/adjacency SIDs) को एन्कोड करते हैं। कोर में कोई प्रति-प्रवाह स्थिति (per-flow state) नहीं।",
    "bgp_idle": "Idle",
    "bgp_connect": "Connect",
    "bgp_active": "Active",
    "bgp_opensent": "OpenSent",
