    "gm_desc": "रेफरेंस क्लॉक (GPS-synced)।",
    "bc_title": "Boundary Clock (BC):",
    "bc_desc": "Nexus स्विच की भूमिका। PTP को समाप्त और पुनर्जीवित करता है, जिससे जिटर (jitter) संचय को रोका जा सकता है।",
    "slave_title": "Slave / Follower:",
