    "nbm_title": "Non-Blocking Multicast (NBM)",
    "nbm_desc": "NBM, Nexus 9000 के लिए एक विशेष मल्टीकास्ट इंजन है जो \"SDI-जैसा\" नियतात्मक व्यवहार सुनिश्चित करता है।",
    "core_benefits": "मुख्य लाभ (Core Benefits):",
    "zero_loss": "शून्य पैकेट हानि (Zero Packet Loss):",
    "zero_loss_desc": "सख्त बैंडविड्थ एडमिशन कंट्रोल।",
    "active_mode": "एक्टिव मोड (Active Mode):",
    "active_mode_desc": "कॉन्फ़िगर की गई फ्लो पॉलिसी वैल्यूज़ (वास्तविक ट्रैफ़िक नहीं) के आधार पर बैंडविड्थ एडमिशन कंट्रोल। स्विच NDFC फ्लो पॉलिसी के अनुसार बैंडविड्थ रिजर्व करता है।",
    "passive_mode": "पैसिव मोड (Passive Mode):",
