    "ptp_hierarchy_desc": "PTP पदानुक्रम Best Master Clock Algorithm (BMCA) द्वारा निर्धारित किया जाता है। कम प्रायोरिटी वैल्यूज़ GM चुनाव जीतते हैं। प्रत्येक Boundary Clock PTP को समाप्त और पुनर्जीवित करता है, जिससे डाउनस्ट्रीम डिवाइस अपस्ट्रीम जिटर से अलग रहते हैं। IPFM में, GM (एक समर्पित GPS उपकरण) {directly} जुड़ता है — Spines पहली BC टियर हैं और आरेख सही ढंग से GM को उनके ऊपर दिखाता है।",
