    "disclaimer": "स्विच PoE बजट वेंडर डेटाशीट से लिए गए हैं और सामान्य कॉन्फ़िगरेशन का प्रतिनिधित्व करते हैं। वास्तविक उपलब्ध बजट इंस्टॉल किए गए PSU वाट क्षमता, फर्मवेयर, परिवेश के तापमान और पोर्ट उपयोग पर निर्भर करता है। तैनाती से पहले हमेशा अपने विशिष्ट हार्डवेयर संशोधन और डेटाशीट के साथ सत्यापित करें।"
