    "t568b_desc": "T568B — उत्तर अमेरिकी व्यावसायिक तैनाती में प्रमुख। पिन 1-2 पर नारंगी पेयर। पेयर 2 और 3 को स्वैप करने के साथ विद्युत रूप से T568A के समान।",
