    "notes_bbr": "लॉस के तहत सबसे अच्छा थ्रूपुट; यदि ट्यून नहीं किया गया तो कतार लग सकती है",
    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "लिनक्स TCP ट्यूनिंग (sysctl)",
    "sysctl_subtitle": "अपने पथ मापदंडों के लिए लिनक्स TCP बफ़र्स और कंजेशन कंट्रोल को ट्यून करने के लिए sysctl कमांड जनरेट करें।",
    "sysctl_algo": "कंजेशन कंट्रोल एल्गोरिदम",
    "sysctl_apply_hint": "इसके साथ लागू करें: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. मान आपके BDP से गणना किए जाते हैं।",
    "ref_title": "एल्गोरिदम संदर्भ",
    "ref_reno_desc": "क्लासिक AIMD एल्गोरिदम। स्लो स्टार्ट ssthresh तक प्रत्येक RTT में cwnd को दोगुना करता है। कंजेशन अवॉइडेंस प्रति RTT ~1 सेगमेंट जोड़ता है। 3 डुप्लिकेट ACKs पर: ssthresh = cwnd/2, cwnd = ssthresh. टाइमआउट पर: cwnd = 1 MSS. निष्पक्ष लेकिन लॉस के बाद उच्च-BDP पथों का कम उपयोग करता है।",
    "ref_cubic_desc": "लिनक्स में डिफ़ॉल्ट। क्यूबिक फ़ंक्शन W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7) का उपयोग करता है। लॉस के बाद, cwnd W_max के 70% तक गिर जाता है, फिर अवतल-उत्तल वक्र के माध्यम से बढ़ता है। लॉन्ग-फैट नेटवर्क पर Reno से अधिक आक्रामक। K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "गूगल का मॉडल-आधारित एल्गोरिदम। लॉस को सिग्नल के रूप में उपयोग करने के बजाय बाधा बैंडविड्थ और न्यूनतम RTT का अनुमान लगाता है। चरण: Startup (2.89x लाभ), Drain, ProbeBW (8-चरण लाभ चक्र: 1.25/0.75/1...), ProbeRTT (हर ~10 सेकंड में 4 सेगमेंट)। लॉस के साथ भी पूर्ण थ्रूपुट प्राप्त करता है।",
    "phase_startup": "Startup",
