    "cni_desc": "कुबेरनेट्स CNI प्लगइन्स पॉड नेटवर्किंग को संभालते हैं। डॉकर नेटवर्क बनाम मुख्य अंतर: प्रति-पॉड IP, नेटवर्क नीतियां, डिफ़ॉल्ट रूप से कोई NAT नहीं।",
    "cni_model": "डेटा प्लेन",
    "cni_policy": "नेटवर्क नीति",
    "cni_perf": "प्रदर्शन",
    "cni_enc": "एन्क्रिप्शन",
    "cni_usecase": "सर्वश्रेष्ठ इसके लिए",
    "cni_vs_docker": "डॉकर नेटवर्क होस्ट-स्कोप (ब्रिज) या स्वार्म-स्कोप (ओवरले) होते हैं। K8s CNI प्लगइन्स क्लस्टर-व्यापी फ्लैट पॉड नेटवर्किंग प्रदान करते हैं जहाँ प्रत्येक पॉड को NAT के बिना एक रूटेबल IP मिलता है।",
    "desc_bridge": "डॉकर होस्ट पर सॉफ़्टवेयर ब्रिज — डिफ़ॉルト मोड। कंटेनर एक सबनेट साझा करते हैं, बाहरी दुनिया के लिए NAT। एकल-होस्ट अनुप्रयोगों के लिए सर्वश्रेष्ठ।",
    "desc_overlay": "VXLAN एनकैप्सुलेशन का उपयोग करने वाला मल्टी-होस्ट ओवरले — डॉकर स्वार्म की आवश्यकता होती है। विभिन्न होस्ट पर कंटेनर समान L2 सेगमेंट पर दिखाई देते हैं।",
    "desc_macvlan": "प्रत्येक कंटेनर को सीधे पैरेंट NIC के L2 सेगमेंट पर अपना स्वयं का MAC и IP मिलता है। शून्य NAT, कोई ब्रिज नहीं। उन लेगेसी ऐप्स के लिए बढ़िया जिन्हें सीधे L2 एक्सेस की आवश्यकता होती है।",
    "desc_ipvlan": "MACVLAN के समान लेकिन सभी कंटेनर पैरेंट MAC साझा करते हैं। L3 मोड कंटेनर IP को रूट करता है — बड़े परिनियोजन पर ARP स्टॉर्म जोखिम को समाप्त करता है।",
    "desc_host": "कंटेनर सीधे होस्ट नेटवर्क नेमस्पेस साझा करता है — कोई अलगाव नहीं, अधिकतम प्रदर्शन। निगरानी एजेंटों जैसे विलंबता-संवेदनशील वर्कलोड के लिए उपयोग करें।",
    "desc_none": "लूपबैक के अलावा कोई network interface नहीं। पूर्ण नेटवर्क अलगाव। तब उपयोग करें जब कंटेनर को किसी network access की आवश्यकता न हो।",
