    "proto_scp_notes": "Secure Copy प्रोटोकॉल। SSH एन्क्रिप्शन के कारण पुराने नेटवर्क डिवाइस पर उच्च CPU ओवरहेड।",
    "proto_sftp_notes": "SSH फ़ाइल ट्रांसफर प्रोटोकॉल। मानक सुरक्षित ट्रांसपोर्ट। प्रोटोकॉल ओवरहेड के कारण SCP से थोड़ा धीमा।",
    "proto_tftp_notes": "ट्रिवियल FTP। लॉकस्टेप ब्लॉक-दर-ब्लॉक ट्रांसफर। लेटेंसी से काफी सीमित। मानक ब्लॉक आकार इसे ~1.5 - 3.5 Mbps तक सीमित करता है।",
    "proto_ftp_notes": "फ़ाइल ट्रांसफर प्रोटोकॉल। बहुत कम ओवरहेड, तेज़ लेकिन बिना एन्क्रिप्शन। क्रेडेंशियल सादे टेक्स्ट में भेजे जाते हैं।",
    "proto_http_notes": "हाइपरटेक्स्ट ट्रांसफर प्रोटोकॉल। तेज़, कम ओवरहेड। लोकल स्टेजिंग सर्वर के लिए उत्तम।",
    "proto_https_notes": "HTTP सुरक्षित। आधुनिक ZTP / क्लाउड डाउनलोड के लिए मानक। मध्यम क्रिप्टोग्राफिक ओवरहेड।",
    "plat_iosxe": "Cisco IOS / IOS-XE",
    "plat_iosxr": "Cisco IOS-XR",
    "plat_nxos": "Cisco NX-OS",
    "plat_junos": "Juniper Junos",
    "plat_eos": "Arista EOS",
    "plat_fortios": "Fortinet FortiOS",
    "plat_panos": "Palo Alto PAN-OS",
    "plat_linux": "Linux (curl / wget / scp)",
    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "\"show flash:\" का उपयोग करके सुनिश्चित करें कि फ्लैश फ़ाइल सिस्टम में पर्याप्त खाली स्थान है। SCP का उपयोग करने पर, सर्वर पर \"ip scp server enable\" कॉन्फ़िगर होना चाहिए, या डिवाइस पर SSH रूटिंग सक्षम होनी चाहिए।",
    "plat_iosxr_notes": "IOS-XR फ़ाइल सिस्टम flash: के बजाय disk0: या disk1: का उपयोग करते हैं। XR में SCP/SFTP कमांड उपयोगकर्ता पासवर्ड इंटरैक्टिव रूप से पूछते हैं। रूटिंग संदर्भ (VRF) वैश्विक स्तर पर कॉन्फ़िगर किया जा सकता है।",
    "plat_nxos_notes": "NX-OS डिफ़ॉल्ट रूप से bootflash: का उपयोग करता है। \"dir bootflash:\" से फ़ाइल सिस्टम स्थान सत्यापित करें। VRF का सर्वर तक IP पहुंच होनी चाहिए; डिफ़ॉल्ट रूटिंग या मैनेजमेंट VRF जांचें।",
    "plat_junos_notes": "Junos पर फ़ाइल कॉपियाँ /var/tmp/ या /var/db/config/ में रखी जाती हैं। डिस्क स्थान जांचने के लिए \"show system storage\" का उपयोग करें। TFTP ट्रांसफर के लिए Junos रूटिंग प्रोटोकॉल कॉन्फ़िगरेशन या routing-instance कीवर्ड का उपयोग आवश्यक हो सकता है।",
    "plat_eos_notes": "Arista डिवाइस flash: का उपयोग करते हैं। \"dir flash:\" से सत्यापित करें। उच्च थ्रूपुट के लिए, Arista अत्यधिक अनुकूलित नेटिव HTTP/HTTPS कॉपी का समर्थन करता है।",
    "plat_fortios_notes": "FortiOS TFTP रिस्टोर बूट इमेज को बदल देता है और डिवाइस को स्वतः रीबूट करता है। सावधानी से उपयोग करें। पहले हमेशा कॉन्फ़िगरेशन फ़ाइलें सहेजें।",
    "plat_panos_notes": "Palo Alto PAN-OS को सॉफ़्टवेयर इंपोर्ट कमांड चलाने के लिए स्पष्ट CLI व्यवस्थापक अनुमतियों की आवश्यकता होती है। सॉफ़्टवेयर को आधिकारिक Palo Alto सपोर्ट अपडेट से भी सीधे डाउनलोड किया जा सकता है।",
    "plat_linux_notes": "लक्ष्य निर्देशिका की रीड/राइट अनुमतियाँ सत्यापित करें। सुनिश्चित करें कि क्लाइंट (scp, curl) इंस्टॉल है। curl/wget के माध्यम से HTTP/HTTPS ट्रांसफर अत्यधिक समानांतरणीय हैं।",
    "plat_f5_notes": "bigstart प्रक्रियाएँ और F5 व्यवस्थापकीय रूट अनुमतियाँ जांचें। गंतव्य फ़ोल्डर /shared/images/ F5 ISO फ़ाइलों के लिए डिफ़ॉल्ट स्थान है।",
    "cmd_iosxe": "! Cisco IOS/IOS-XE कमांड",
    "cmd_iosxr_scp": "! Cisco IOS-XR कमांड (नोट: scp/sftp क्लाइंट के लिए ssh क्लाइंट कॉन्फ़िगरेशन आवश्यक है)",
    "cmd_iosxr": "! Cisco IOS-XR कमांड",
    "cmd_nxos": "! Cisco NX-OS कमांड",
    "cmd_junos": "# Juniper Junos कमांड",
    "cmd_junos_tftp": "# Juniper Junos कमांड (tftp fetch के लिए shell एक्सेस या ftp/http आवश्यक)",
    "cmd_eos": "! Arista EOS कमांड",
    "cmd_fortios_restore": "# FortiOS कमांड (फर्मवेयर रिस्टोर)",
    "cmd_fortios_note": "# FortiOS फर्मवेयर अपडेट आमतौर पर HTTPS / FortiGuard या लोकल GUI अपलोड के माध्यम से किए जाते हैं।",
