    "cap_desc_tree": "ट्री टोपोलॉजी: राउटर Cskip एड्रेस आवंटन एल्गोरिथ्म (Zigbee PRO) का उपयोग करके एक पदानुक्रमित संरचना में नेटवर्क का विस्तार करते हैं। Cm, Rm और Lm स्टैक मापदंडों का उपयोग करके गणना की जाती है।",
    "cap_desc_mesh": "मेश टोपोलॉजी: राउटर अन्य नोड्स के लिए ट्रैफ़िक अग्रेषित करते हैं, जिससे स्व-चिकित्सा पथ सक्षम होते हैं। एड्रेस स्पेस पूर्ण 16-bit रेंज (0x0000–0xFFFF) है। व्यावहारिक सीमाएं रूटिंग टेबल आकार और ट्रैफ़िक लोड पर निर्भर करती हैं।",
