    "explanation_title": "NAT बनाम PAT को समझना",
    "explanation_intro": "नेटवर्क एड्रेस ट्रांसलेशन (NAT) और पोर्ट एड्रेस ट्रांसलेशन (PAT) एक IP एड्रेस स्पेस को दूसरे में मैप करने की तकनीकें हैं, जिनका उपयोग मुख्य रूप से सीमित सार्वजनिक IPv4 एड्रेस को बचाने या सबनेट संघर्षों को हल करने के लिए किया जाता है।",
    "nat_expl_title": "1. NAT क्या है?",
    "nat_expl_desc": "NAT 1-से-1 आधार पर IP एड्रेस को ट्रांसलेट करता है। यह स्टैटिक (एक प्राइवेट IP का एक पब्लिक IP पर स्थायी मैपिंग, पब्लिक-फेसिंग सर्वर के लिए आदर्श) या डायनेमिक (जरूरत पड़ने पर पूल से प्राइवेट होस्ट को पब्लिक IP आवंटित करता है। एक बार सभी पब्लिक IP असाइन हो जाने के बाद, IP खाली होने तक अगले होस्ट ब्लॉक हो जाते हैं) हो सकता है। पोर्ट नंबर अपरिवर्तित रहते हैं।",
    "pat_expl_title": "2. PAT (NAT ओवरलोड) क्या है?",
    "pat_expl_desc": "PAT (या पोर्ट एड्रेस ट्रांसलेशन / NAT ओवरलोड) मेनी-टू-वन (N-से-1) आधार पर IP एड्रेस और सोर्स पोर्ट नंबर दोनों को ट्रांसलेट करता है। कई प्राइवेट होस्ट अद्वितीय सोर्स पोर्ट असाइन करके एक ही पब्लिक IP एड्रेस साझा करते हैं (जैसे 192.168.1.10:5000 और 192.168.1.11:5000 को 203.0.113.10:1024 और 203.0.113.10:1025 पर मैप किया जाता है)। यह होम राउटर और एंटरप्राइज इंटरनेट एक्सेस के लिए मानक तरीका है।",
    "comparison_table_title": "तुलना सारांश",
    "comp_header_feature": "विशेषता",
    "comp_header_nat": "NAT (1-से-1)",
    "comp_header_pat": "PAT (N-से-1 / ओवरलोड)",
