    "tab_parse": "एनटीपीक्यू/क्रॉनिक को पार्स करें",
    "hierarchy_hint": "एनटीपी एक स्तरित पदानुक्रम में समय सर्वरों को व्यवस्थित करता है। प्रत्येक स्तर का स्तर एक आधिकारिक संदर्भ घड़ी से एक हॉप आगे है। निचला स्तर = अधिक सटीक।",
    "stratum_prefix": "स्ट्रेटम",
    "stratum0_label": "स्ट्रेटम 0 - संदर्भ घड़ियाँ",
    "stratum0_desc": "उच्च परिशुद्धता टाइमकीपिंग हार्डवेयर सीधे सर्वर से जुड़ा हुआ है। स्वयं नेटवर्क पर पहुंच योग्य नहीं - वे सीधे स्थानीय कनेक्शन के माध्यम से स्ट्रैटम 1 सर्वर को फीड करते हैं।",
    "stratum0_examples": "जीपीएस रिसीवर, परमाणु घड़ियाँ (सीज़ियम/रुबिडियम), रेडियो घड़ियाँ (DCF77, WWVB, MSF), PPS (पल्स-प्रति-सेकंड) स्रोत",
    "stratum1_label": "स्ट्रेटम 1 - प्राथमिक एनटीपी सर्वर",
    "stratum1_desc": "सर्वर सीधे स्ट्रैटम 0 संदर्भ घड़ी से जुड़े हुए हैं। ये नेटवर्क पर पहुंच योग्य सबसे सटीक एनटीपी सर्वर हैं। अक्सर शीर्ष-स्तरीय पूल सर्वर के रूप में उपयोग किया जाता है।",
    "stratum1_examples": "time.nist.gov, time.cloudflare.com, ntp1.example.com (GPS के साथ), पूल.ntp.org स्ट्रैटम 1 सदस्य",
    "stratum2_label": "स्ट्रेटम 2 - द्वितीयक सर्वर",
    "stratum2_desc": "स्ट्रैटम 1 सर्वर से सिंक्रोनाइज़ किया गया। अधिकांश उद्यम और सार्वजनिक तैनाती के लिए संदर्भ के रूप में उपयुक्त। एक छोटी सी अतिरिक्त अनिश्चितता का परिचय दें.",
    "stratum2_examples": "पूल.ntp.org सर्वर, क्षेत्रीय एनटीपी सर्वर, कॉर्पोरेट एनटीपी इंफ्रास्ट्रक्चर सहकर्मी",
    "stratum3_label": "स्ट्रेटम 3 - तृतीयक सर्वर",
    "stratum3_desc": "स्ट्रैटम 2 से सिंक्रनाइज़। लगभग सभी व्यावहारिक अनुप्रयोगों के लिए अभी भी पर्याप्त सटीक है। डाउनस्ट्रीम एंटरप्राइज़ एनटीपी सर्वर के लिए विशिष्ट।",
    "stratum3_examples": "शाखा कार्यालय एनटीपी सर्वर, द्वितीयक उद्यम एनटीपी रिले",
    "stratum4_15_label": "स्ट्रेटम 4-15 - अतिरिक्त परतें",
    "stratum4_15_desc": "प्रत्येक बाद की परत एक स्ट्रेटम हॉप जोड़ती है। अधिकतम प्रयोग करने योग्य स्तर 15 है। प्रत्येक हॉप पर सटीकता थोड़ी कम हो जाती है लेकिन अधिकांश अनुप्रयोगों के लिए पर्याप्त रहती है। स्ट्रैटम 5 के ऊपर सावधानी से प्रयोग करें।",
    "stratum4_15_examples": "गहन उद्यम पदानुक्रम, पृथक नेटवर्क, एम्बेडेड डिवाइस एनटीपी क्लाइंट",
    "stratum16_label": "स्ट्रैटम 16 - अनसिंक्रनाइज़्ड",
    "stratum16_desc": "16 के स्ट्रेटम मान का मतलब है कि सर्वर ने सिंक्रनाइज़ेशन खो दिया है और इसे समय स्रोत के रूप में उपयोग नहीं किया जाना चाहिए। ग्राहक इसे अस्वीकार कर देंगे.",
    "stratum16_examples": "ntpd/chronyd जिसने सभी अपस्ट्रीम स्रोतों को खो दिया है, प्रारंभिक सिंक से पहले नए सिरे से डेमॉन शुरू किया है",
    "note_label": "टिप्पणियाँ",
    "notes_text": "अधिकतम प्रयोग योग्य स्ट्रैटम 15 है। स्ट्रैटम 16 का अर्थ है अनसिंक्रनाइज़्ड। 16 से ऊपर के मान आरक्षित हैं। जब कोई सर्वर किस-ओ'-डेथ (KoD) पैकेट भेजता है, तो स्ट्रैटम फ़ील्ड 0 पर सेट होता है और रिफिड कारण को एनकोड करता है।",
    "rfc5905_label": "एनटीपीवी4 विशिष्टता",
